<script setup lang="ts">
defineProps<{duration:number;start:number;end:number;previewState:'idle'|'loading'|'ready'|'playing'|'paused';loop:boolean}>(); const emit=defineEmits<{updateStart:[n:number];updateEnd:[n:number];analyze:[];togglePreview:[];toggleLoop:[loop:boolean]}>();
</script>
<template><section class="stage-card"><span class="kicker">02 / TRIM THE MOMENT</span><h2>留下最有表情的十秒</h2><div class="timeline"><div class="timeline-fill" :style="{left:`${start/duration*100||0}%`,right:`${100-(end/duration*100||0)}%`}"></div></div><div class="range-pair"><label>起点 {{ start.toFixed(1) }}s<input type="range" min="0" :max="Math.max(0,duration-.1)" step=".1" :value="start" @input="emit('updateStart',Number(($event.target as HTMLInputElement).value))"></label><label>终点 {{ end.toFixed(1) }}s<input type="range" :min="Math.min(duration,start+.1)" :max="duration" step=".1" :value="end" @input="emit('updateEnd',Number(($event.target as HTMLInputElement).value))"></label></div><div class="preview-bar"><button data-testid="preview-toggle" type="button" :disabled="previewState==='loading'" @click="emit('togglePreview')">{{ previewState==='playing'?'⏸ 暂停试听':previewState==='paused'?'▶ 继续试听':previewState==='loading'?'准备试听…':'▶ 试听片段' }}</button><button data-testid="preview-loop" type="button" :class="{active:loop}" :aria-pressed="loop" @click="emit('toggleLoop',!loop)">{{ loop?'↻ 循环中':'↻ 循环试听' }}</button><span class="preview-hint">{{ previewState==='playing'?(loop?'正在循环试听所选片段':'正在试听所选片段'):'试听听到的就是将要分析和保存的声音' }}</span></div><button data-testid="analyze" class="acid-button" type="button" @click="emit('analyze')">分析这段声音 →</button></section></template>
